import re as _re

def _t():

    def getter(self):
        return 42

    def setter(self, value):
        pass

    class A:

        @property
        def foo(self):
            return 1

        @foo.setter
        def oof(self, value):
            pass
        bar = property(getter)
        baz = property(None, setter)
    assert A.foo.__name__ == 'foo', ('assertEqual', A.foo.__name__, 'foo')
    assert A.oof.__name__ == 'oof', ('assertEqual', A.oof.__name__, 'oof')
    assert A.bar.__name__ == 'bar', ('assertEqual', A.bar.__name__, 'bar')
    assert A.baz.__name__ == 'baz', ('assertEqual', A.baz.__name__, 'baz')
    A.quux = property(getter)
    assert A.quux.__name__ == 'getter', ('assertEqual', A.quux.__name__, 'getter')
    A.quux.__name__ = 'myquux'
    assert A.quux.__name__ == 'myquux', ('assertEqual', A.quux.__name__, 'myquux')
    assert A.bar.__name__ == 'bar', ('assertEqual', A.bar.__name__, 'bar')
    A.quux.__name__ = None
    assert A.quux.__name__ is None, ('assertIsNone', A.quux.__name__)
    try:
        property(None, setter).__name__
    except AttributeError as _exc:
        assert _re.search("'property' object has no attribute '__name__'", str(_exc)), 'assertRaisesRegex: message mismatch'
    else:
        raise AssertionError('assertRaises: did not raise')
    try:
        property(1).__name__
    except AttributeError as _exc:
        assert _re.search("'property' object has no attribute '__name__'", str(_exc)), 'assertRaisesRegex: message mismatch'
    else:
        raise AssertionError('assertRaises: did not raise')

    class Err:

        def __getattr__(self, attr):
            raise RuntimeError('fail')
    p = property(Err())
    try:
        p.__name__
    except RuntimeError as _exc:
        assert _re.search('fail', str(_exc)), 'assertRaisesRegex: message mismatch'
    else:
        raise AssertionError('assertRaises: did not raise')
    p.__name__ = 'not_fail'
    assert p.__name__ == 'not_fail', ('assertEqual', p.__name__, 'not_fail')
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

